/**
 * @typedef {import('../types.d.ts').RuleExpression} RuleExpression
 * @typedef {import('../types.d.ts').ComparisonOptions} ComparisonOptions
 * @typedef {import('../types.d.ts').StringOptions} StringOptions
 * @typedef {import('../types.d.ts').FieldHelpers} FieldHelpers
 * @typedef {import('../types.d.ts').ValidationHelpers} ValidationHelpers
 */
/**
 * Rule building helpers
 * Makes it easy to construct rules without memorizing operator syntax
 */
export class RuleHelpers {
    ops: {
        EQ: string;
        NEQ: string;
        GT: string;
        GTE: string;
        LT: string;
        LTE: string;
        IN: string;
        NOT_IN: string;
        AND: string;
        OR: string;
        NOT: string;
        CONTAINS: string;
        STARTS_WITH: string;
        ENDS_WITH: string;
        REGEX: string;
        BETWEEN: string;
        IS_NULL: string;
        IS_NOT_NULL: string;
    };
    /**
     * Equal to
     * @param {string|number} left - Left operand (path or value)
     * @param {string|number|boolean} right - Right operand (path or value)
     * @param {ComparisonOptions} [options] - Optional comparison options
     * @returns {RuleExpression} Rule expression object
     */
    eq(left: string | number, right: string | number | boolean, options?: ComparisonOptions, ...args: any[]): RuleExpression;
    /**
     * Not equal to
     * @param {string|number} left - Left operand (path or value)
     * @param {string|number|boolean} right - Right operand (path or value)
     * @param {ComparisonOptions} [options] - Optional comparison options
     * @returns {RuleExpression} Rule expression object
     */
    neq(left: string | number, right: string | number | boolean, options?: ComparisonOptions, ...args: any[]): RuleExpression;
    /**
     * Greater than
     * @param {string|number} left - Left operand (path or value)
     * @param {string|number} right - Right operand (path or value)
     * @param {ComparisonOptions} [options] - Optional comparison options
     * @returns {RuleExpression} Rule expression object
     */
    gt(left: string | number, right: string | number, options?: ComparisonOptions, ...args: any[]): RuleExpression;
    /**
     * Greater than or equal
     * @param {string|number} left - Left operand (path or value)
     * @param {string|number} right - Right operand (path or value)
     * @param {ComparisonOptions} [options] - Optional comparison options
     * @returns {RuleExpression} Rule expression object
     */
    gte(left: string | number, right: string | number, options?: ComparisonOptions, ...args: any[]): RuleExpression;
    /**
     * Less than
     * @param {string|number} left - Left operand (path or value)
     * @param {string|number} right - Right operand (path or value)
     * @param {ComparisonOptions} [options] - Optional comparison options
     * @returns {RuleExpression} Rule expression object
     */
    lt(left: string | number, right: string | number, options?: ComparisonOptions, ...args: any[]): RuleExpression;
    /**
     * Less than or equal
     * @param {string|number} left - Left operand (path or value)
     * @param {string|number} right - Right operand (path or value)
     * @param {ComparisonOptions} [options] - Optional comparison options
     * @returns {RuleExpression} Rule expression object
     */
    lte(left: string | number, right: string | number, options?: ComparisonOptions, ...args: any[]): RuleExpression;
    /**
     * Logical AND - all conditions must be true
     * @param {...RuleExpression} expressions - Rule expressions to AND together
     * @returns {RuleExpression} Combined rule expression
     */
    and(...expressions: RuleExpression[]): RuleExpression;
    /**
     * Logical OR - at least one condition must be true
     * @param {...RuleExpression} expressions - Rule expressions to OR together
     * @returns {RuleExpression} Combined rule expression
     */
    or(...expressions: RuleExpression[]): RuleExpression;
    /**
     * Logical NOT - negates the expression
     * @param {RuleExpression} expression - Rule expression to negate
     * @returns {RuleExpression} Negated rule expression
     */
    not(expression: RuleExpression): RuleExpression;
    /**
     * String contains
     * @param {string} left - Path to the string field
     * @param {string} right - Substring to search for
     * @param {StringOptions} [options] - Optional string options
     * @returns {RuleExpression} Rule expression object
     */
    contains(left: string, right: string, options?: StringOptions, ...args: any[]): RuleExpression;
    /**
     * String starts with
     * @param {string} left - Path to the string field
     * @param {string} right - Prefix to check for
     * @param {StringOptions} [options] - Optional string options
     * @returns {RuleExpression} Rule expression object
     */
    startsWith(left: string, right: string, options?: StringOptions, ...args: any[]): RuleExpression;
    /**
     * String ends with
     * @param {string} left - Path to the string field
     * @param {string} right - Suffix to check for
     * @param {StringOptions} [options] - Optional string options
     * @returns {RuleExpression} Rule expression object
     */
    endsWith(left: string, right: string, options?: StringOptions, ...args: any[]): RuleExpression;
    /**
     * Regular expression match
     * @param {string} left - Path to the string field
     * @param {string} right - Regular expression pattern
     * @param {StringOptions} [options] - Optional string options
     * @returns {RuleExpression} Rule expression object
     */
    regex(left: string, right: string, options?: StringOptions, ...args: any[]): RuleExpression;
    /**
     * Value is in array (includes)
     * @param {string} left - Path to the value
     * @param {unknown[]|string} right - Array of values to check against or string separated by dot (path to array of values)
     * @param {ComparisonOptions} [options] - Optional comparison options
     * @returns {RuleExpression} Rule expression object
     */
    in(left: string, right: unknown[] | string, options?: ComparisonOptions, ...args: any[]): RuleExpression;
    /**
     * Value is not in array (not includes)
     * @param {string} left - Path to the value
     * @param {unknown[] | string} right - Array of values to check against or string separated by dot (path to array of values)
     * @param {ComparisonOptions} [options] - Optional comparison options
     * @returns {RuleExpression} Rule expression object
     */
    notIn(left: string, right: unknown[] | string, options?: ComparisonOptions, ...args: any[]): RuleExpression;
    /**
     * Value is between min and max (inclusive)
     * @param {string} value - Path to the value
     * @param {[number, number]} range - [min, max] range tuple
     * @param {ComparisonOptions} [options] - Optional comparison options
     * @returns {RuleExpression} Rule expression object
     */
    between(value: string, range: [number, number], options?: ComparisonOptions, ...args: any[]): RuleExpression;
    /**
     * Value is null or undefined
     * @param {string} path - Path to the value
     * @returns {RuleExpression} Rule expression object
     */
    isNull(path: string): RuleExpression;
    /**
     * Value is not null and not undefined
     * @param {string} path - Path to the value
     * @returns {RuleExpression} Rule expression object
     */
    isNotNull(path: string): RuleExpression;
    /**
     * Field equals true
     * @param {string} path - Path to the boolean field
     * @returns {RuleExpression} Rule expression object
     */
    isTrue(path: string): RuleExpression;
    /**
     * Field equals false
     * @param {string} path - Path to the boolean field
     * @returns {RuleExpression} Rule expression object
     */
    isFalse(path: string): RuleExpression;
    /**
     * Field equals empty string
     * @param {string} path - Path to the string field
     * @returns {RuleExpression} Rule expression object
     */
    isEmpty(path: string): RuleExpression;
    /**
     * Field does not equal empty string
     * @param {string} path - Path to the string field
     * @returns {RuleExpression} Rule expression object
     */
    isNotEmpty(path: string): RuleExpression;
    /**
     * Field has any truthy value (exists and is not empty/false)
     * @param {string} path - Path to the field
     * @returns {RuleExpression} Rule expression object
     */
    exists(path: string): RuleExpression;
    /**
     * Initialize field comparison helpers
     * @returns {void}
     * @private
     */
    private _initializeFieldHelpers;
    /**
     * Field comparison helpers for comparing two fields dynamically
     * @type {FieldHelpers}
     */
    field: FieldHelpers;
    /**
     * Initialize validation helpers
     * @returns {void}
     * @private
     */
    private _initializeValidationHelpers;
    /**
     * Validation pattern helpers for common validation rules
     * @type {ValidationHelpers}
     */
    validation: ValidationHelpers;
}
export type RuleExpression = import("../types.d.ts").RuleExpression;
export type ComparisonOptions = import("../types.d.ts").ComparisonOptions;
export type StringOptions = import("../types.d.ts").StringOptions;
export type FieldHelpers = import("../types.d.ts").FieldHelpers;
export type ValidationHelpers = import("../types.d.ts").ValidationHelpers;
